def analyze_payments():
    history = lookup_payment_history(account_id="ACME-9000")
    payments_2025 = []
    for p in history["payments"]:
        if p["paid"].startswith("2025"):
            payments_2025.append(p)

    total_paid = sum(p["amount"] for p in payments_2025)
    late_payments = sum(1 for p in payments_2025 if p["paid"] > p["due"])
    max_payment = max(p["amount"] for p in payments_2025) if payments_2025 else 0.0

    return {
        "total_paid": round(total_paid, 2),
        "late_payments": late_payments,
        "max_payment": round(max_payment, 2)
    }

print(analyze_payments())

import datetime

def check_dates():
    start_date = datetime.date(2026, 10, 12)
    end_date = datetime.date(2026, 10, 25)
    current_date = start_date

    while current_date <= end_date:
        date_str = current_date.strftime("%Y-%m-%d")
        result = check_availability(date=date_str, party_size=7)
        times = result.get('times', [])

        # Check for 20:30 (8:30 PM) or later
        for time in times:
            hour, minute = map(int, time.split(':'))
            if hour >= 20 and (hour > 20 or minute >= 30):
                return {"found": True, "date": date_str, "time": time}

        current_date += datetime.timedelta(days=1)

    return {"found": False}

print(check_dates())
